// Shared Power Pages Server Logic prelude.
// This file is concatenated into each deployable endpoint at build time.
// It intentionally uses no module/import/require syntax.

const RuntimeConfig = {
  string: function (siteSettingName, environmentVariableName, fallbackValue) {
    let value = null;

    if (siteSettingName) {
      value = Server.SiteSetting.Get(siteSettingName);
    }

    if ((value === null || value === undefined || value === "") && environmentVariableName) {
      value = Server.EnvironmentVariable.get(environmentVariableName);
    }

    if (value === null || value === undefined || value === "") return fallbackValue;
    return String(value);
  },

  boolean: function (siteSettingName, environmentVariableName, fallbackValue) {
    const value = RuntimeConfig.string(
      siteSettingName,
      environmentVariableName,
      fallbackValue ? "true" : "false"
    );
    return String(value).toLowerCase() === "true";
  },

  number: function (siteSettingName, environmentVariableName, fallbackValue) {
    const value = Number(RuntimeConfig.string(
      siteSettingName,
      environmentVariableName,
      String(fallbackValue)
    ));
    return isNaN(value) ? fallbackValue : value;
  }
};

const RuntimeLogger = {
  log: function (level, eventName, details) {
    const entry = {
      level: level,
      event: eventName,
      activityId: Server.Context.ActivityId,
      userId: Server.User ? Server.User.id : null,
      details: details || {}
    };

    Server.Logger.Log(JSON.stringify(entry));
  },

  info: function (eventName, details) {
    RuntimeLogger.log("info", eventName, details);
  },

  warn: function (eventName, details) {
    RuntimeLogger.log("warn", eventName, details);
  },

  error: function (eventName, details) {
    RuntimeLogger.log("error", eventName, details);
  }
};

const RuntimeDataverse = {
  assertSuccess: function (response, operationName) {
    if (!response || !response.IsSuccessStatusCode) {
      const message = response && response.ServerErrorMessage
        ? response.ServerErrorMessage
        : operationName + " failed.";
      throw new Error(message);
    }
    return response;
  },

  body: function (response, fallbackValue) {
    RuntimeDataverse.assertSuccess(response, "Dataverse operation");
    if (!response.Body) return fallbackValue;

    try {
      return JSON.parse(response.Body);
    } catch (error) {
      throw new Error("Dataverse returned an invalid JSON body.");
    }
  }
};

function runtimeError(message, code, retryable) {
  const error = new Error(message);
  error.code = code || "SERVER_ERROR";
  error.retryable = retryable === true;
  return error;
}

// Optional Dataverse-backed idempotency store.
//
// Disabled by default. To enable it, provision a custom Dataverse table with
// an alternate key on the operation-id column and configure the settings below.
//
// Default table contract:
// EntitySetName: ppa_syncoperations
// Primary key:   ppa_syncoperationid
// Operation ID:  ppa_operationid (text, alternate key)
// Status:        ppa_status (text)
// Response:      ppa_response (multiline text)

const IdempotencyStore = {
  enabled: function () {
    return RuntimeConfig.boolean(
      "Sync/IdempotencyEnabled",
      "ppa_SyncIdempotencyEnabled",
      false
    );
  },

  settings: function () {
    return {
      entitySetName: RuntimeConfig.string(
        "Sync/IdempotencyEntitySetName",
        "ppa_SyncIdempotencyEntitySetName",
        "ppa_syncoperations"
      ),
      idColumn: RuntimeConfig.string(
        "Sync/IdempotencyIdColumn",
        "ppa_SyncIdempotencyIdColumn",
        "ppa_syncoperationid"
      ),
      operationColumn: RuntimeConfig.string(
        "Sync/IdempotencyOperationColumn",
        "ppa_SyncIdempotencyOperationColumn",
        "ppa_operationid"
      ),
      statusColumn: RuntimeConfig.string(
        "Sync/IdempotencyStatusColumn",
        "ppa_SyncIdempotencyStatusColumn",
        "ppa_status"
      ),
      responseColumn: RuntimeConfig.string(
        "Sync/IdempotencyResponseColumn",
        "ppa_SyncIdempotencyResponseColumn",
        "ppa_response"
      )
    };
  },

  find: function (operationId) {
    if (!IdempotencyStore.enabled()) return null;

    const settings = IdempotencyStore.settings();
    const query =
      "$select=" +
      settings.idColumn + "," +
      settings.statusColumn + "," +
      settings.responseColumn +
      "&$filter=" + settings.operationColumn + " eq '" + operationId + "'" +
      "&$top=1";

    const response = Server.Connector.Dataverse.RetrieveMultipleRecords(
      settings.entitySetName,
      query,
      true
    );

    const body = RuntimeDataverse.body(response, { value: [] });
    const records = body && Array.isArray(body.value) ? body.value : [];
    return records.length > 0 ? records[0] : null;
  },

  begin: function (operationId) {
    if (!IdempotencyStore.enabled()) {
      return { enabled: false, duplicate: false, recordId: null, response: null };
    }

    const settings = IdempotencyStore.settings();
    const existing = IdempotencyStore.find(operationId);

    if (existing) {
      let savedResponse = null;
      const responseText = existing[settings.responseColumn];

      if (responseText) {
        try {
          savedResponse = JSON.parse(responseText);
        } catch (error) {
          savedResponse = null;
        }
      }

      return {
        enabled: true,
        duplicate: true,
        recordId: existing[settings.idColumn],
        status: existing[settings.statusColumn],
        response: savedResponse
      };
    }

    const createPayload = {};
    createPayload[settings.operationColumn] = operationId;
    createPayload[settings.statusColumn] = "processing";

    RuntimeDataverse.assertSuccess(
      Server.Connector.Dataverse.CreateRecord(
        settings.entitySetName,
        JSON.stringify(createPayload)
      ),
      "Create idempotency record"
    );

    const created = IdempotencyStore.find(operationId);
    if (!created) {
      throw new Error("Idempotency record was created but could not be retrieved.");
    }

    return {
      enabled: true,
      duplicate: false,
      recordId: created[settings.idColumn],
      response: null
    };
  },

  complete: function (recordId, responsePayload) {
    if (!IdempotencyStore.enabled() || !recordId) return;

    const settings = IdempotencyStore.settings();
    const payload = {};
    payload[settings.statusColumn] = "completed";
    payload[settings.responseColumn] = JSON.stringify(responsePayload);

    RuntimeDataverse.assertSuccess(
      Server.Connector.Dataverse.UpdateRecord(
        settings.entitySetName,
        recordId,
        JSON.stringify(payload)
      ),
      "Complete idempotency record"
    );
  },

  fail: function (recordId, errorPayload) {
    if (!IdempotencyStore.enabled() || !recordId) return;

    const settings = IdempotencyStore.settings();
    const payload = {};
    payload[settings.statusColumn] = "failed";
    payload[settings.responseColumn] = JSON.stringify(errorPayload);

    RuntimeDataverse.assertSuccess(
      Server.Connector.Dataverse.UpdateRecord(
        settings.entitySetName,
        recordId,
        JSON.stringify(payload)
      ),
      "Fail idempotency record"
    );
  }
};

const WORK_ORDERS = "msdyn_workorders";
const MAX_BATCH_SIZE = 20;
const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const SYSTEM_STATUS = {
  inProgress: 690970002,
  completed: 690970003
};

function assertGuid(value, name) {
  if (!value || !GUID.test(value)) throw new Error(name + " must be a valid GUID.");
}

function assertIsoDate(value, name) {
  if (!value) return;
  const time = new Date(value).getTime();
  if (isNaN(time)) throw new Error(name + " must be an ISO-8601 date/time.");
}

function assertNotStale(recordId, baseModifiedOn) {
  if (!baseModifiedOn) return;

  assertIsoDate(baseModifiedOn, "baseModifiedOn");

  const response = Server.Connector.Dataverse.RetrieveRecord(
    WORK_ORDERS,
    recordId,
    "$select=modifiedon",
    true
  );

  const remote = RuntimeDataverse.body(response, {});
  if (!remote.modifiedon) return;

  const localTime = new Date(baseModifiedOn).getTime();
  const remoteTime = new Date(remote.modifiedon).getTime();

  if (localTime !== remoteTime) {
    throw runtimeError(
      "The Work Order changed on the server after this offline draft was created.",
      "CONFLICT",
      false
    );
  }
}

function mapOperationToDataverse(operation) {
  if (operation.operation !== "submitWorkOrderExecution") {
    throw runtimeError("Unsupported operation: " + operation.operation, "VALIDATION", false);
  }

  assertGuid(operation.operationId, "operationId");
  assertGuid(operation.recordId, "recordId");

  const payload = operation.payload || {};
  if (payload.workOrderId !== operation.recordId) {
    throw runtimeError("payload.workOrderId must match recordId.", "VALIDATION", false);
  }

  if (!SYSTEM_STATUS[payload.status]) {
    throw runtimeError("status must be inProgress or completed.", "VALIDATION", false);
  }

  const technicianNote = typeof payload.technicianNote === "string"
    ? payload.technicianNote.trim()
    : "";

  if (technicianNote.length > 8000) {
    throw runtimeError("technicianNote must be 8000 characters or less.", "VALIDATION", false);
  }

  if (typeof payload.followUpRequired !== "boolean") {
    throw runtimeError("followUpRequired must be boolean.", "VALIDATION", false);
  }

  assertIsoDate(payload.arrivedOn, "arrivedOn");
  assertIsoDate(payload.completedOn, "completedOn");

  if (payload.status === "completed" && !payload.completedOn) {
    throw runtimeError("completedOn is required for completed status.", "VALIDATION", false);
  }

  assertNotStale(operation.recordId, payload.baseModifiedOn);

  const patch = {
    msdyn_systemstatus: SYSTEM_STATUS[payload.status],
    msdyn_followuprequired: payload.followUpRequired
  };

  if (technicianNote) patch.msdyn_followupnote = technicianNote;
  if (payload.arrivedOn) patch.msdyn_firstarrivedon = payload.arrivedOn;
  if (payload.completedOn) patch.msdyn_completedon = payload.completedOn;

  return patch;
}

function post() {
  const writesEnabled = RuntimeConfig.boolean(
    "FieldService/EnableWriteDemo",
    "ppa_FieldServiceEnableWriteDemo",
    false
  );

  if (!writesEnabled) {
    throw new Error(
      "Field Service synchronization writes are disabled. Enable only after security, licensing and idempotency review."
    );
  }

  const body = JSON.parse(Server.Context.Body || "{}");
  const operations = body.operations;

  if (!Array.isArray(operations) || operations.length === 0) {
    throw new Error("operations must be a non-empty array.");
  }

  if (operations.length > MAX_BATCH_SIZE) {
    throw new Error("Maximum batch size is " + MAX_BATCH_SIZE + ".");
  }

  const results = [];

  for (let i = 0; i < operations.length; i++) {
    const operation = operations[i];
    let idempotencyState = null;

    try {
      assertGuid(operation.operationId, "operationId");
      idempotencyState = IdempotencyStore.begin(operation.operationId);

      if (idempotencyState.duplicate) {
        if (idempotencyState.status === "completed" && idempotencyState.response) {
          results.push(idempotencyState.response);
          continue;
        }

        results.push({
          operationId: operation.operationId,
          recordId: operation.recordId,
          status: "rejected",
          code: "IDEMPOTENCY_IN_PROGRESS",
          retryable: true,
          error: "This operation is already being processed."
        });
        continue;
      }

      const patch = mapOperationToDataverse(operation);

      RuntimeDataverse.assertSuccess(
        Server.Connector.Dataverse.UpdateRecord(
          WORK_ORDERS,
          operation.recordId,
          JSON.stringify(patch)
        ),
        "Update Work Order"
      );

      const applied = {
        operationId: operation.operationId,
        recordId: operation.recordId,
        status: "applied",
        retryable: false
      };

      IdempotencyStore.complete(idempotencyState.recordId, applied);
      results.push(applied);

      RuntimeLogger.info("field_service_sync.applied", {
        operationId: operation.operationId,
        recordId: operation.recordId
      });
    } catch (error) {
      const rejected = {
        operationId: operation && operation.operationId ? operation.operationId : "unknown",
        recordId: operation && operation.recordId ? operation.recordId : "unknown",
        status: "rejected",
        code: error && error.code ? error.code : "SERVER_ERROR",
        retryable: error && error.retryable === true,
        error: error && error.message ? error.message : String(error)
      };

      if (idempotencyState && !idempotencyState.duplicate) {
        try {
          IdempotencyStore.fail(idempotencyState.recordId, rejected);
        } catch (idempotencyError) {
          RuntimeLogger.error("idempotency.fail_record_failed", {
            operationId: rejected.operationId
          });
        }
      }

      results.push(rejected);

      RuntimeLogger.warn("field_service_sync.rejected", {
        operationId: rejected.operationId,
        recordId: rejected.recordId,
        code: rejected.code,
        retryable: rejected.retryable
      });
    }
  }

  return JSON.stringify({ results: results });
}
